<?php namespace App\Filament\Resources\ArticleResource\Pages; use App\Filament\Resources\ArticleResource; use App\Models\Article; use App\Services\EditorialTrash; use Filament\Actions\{Action,CreateAction}; use Filament\Resources\Pages\ListRecords; use Filament\Schemas\Components\Tabs\Tab; use Illuminate\Database\Eloquent\Builder; class ListArticles extends ListRecords {protected static string $resource=ArticleResource::class; protected function getHeaderActions():array{return [CreateAction::make()->visible(fn (): bool => $this->activeTab !== 'trash'),Action::make('empty_trash')->label('Vider la Corbeille')->icon('heroicon-o-trash')->color('danger')->requiresConfirmation()->modalHeading('Vider la Corbeille ?')->modalDescription('Tous les articles seront supprimés définitivement. Le comportement SEO des anciennes URL sera conservé.')->visible(fn (): bool => $this->activeTab === 'trash' && Article::onlyTrashed()->exists())->action(fn () => app(EditorialTrash::class)->emptyTrash(Article::class))];} public function getTabs():array{return ['active'=>Tab::make('Articles')->badge(Article::query()->count()),'trash'=>Tab::make('Corbeille')->badge(Article::onlyTrashed()->count())->modifyQueryUsing(fn (Builder $query): Builder => $query->onlyTrashed())];}}
